package com.gymflow.supplier;import com.gymflow.gym.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@Service public class SupplierService{private final SupplierRepository suppliers;private final GymRepository gyms;public SupplierService(SupplierRepository s,GymRepository g){suppliers=s;gyms=g;}@Transactional public SupplierResponse create(UUID gymId,SupplierRequest r){Gym gym=gyms.findById(gymId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Gimnasio no encontrado."));if(suppliers.existsByGym_IdAndNameIgnoreCase(gymId,r.name().trim()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Ya existe ese proveedor.");return SupplierResponse.from(suppliers.save(new Supplier(gym,r.name().trim(),clean(r.email()),clean(r.phone()),clean(r.notes()))));}@Transactional(readOnly=true)public List<SupplierResponse> findAll(UUID gymId){return suppliers.findAllByGym_IdOrderByName(gymId).stream().map(SupplierResponse::from).toList();}private String clean(String s){return s==null||s.isBlank()?null:s.trim();}}
